mapper.select:
SELECT b.card_id
  FROM benefit b
 WHERE b.is_active = 'Y'
   AND b.benefit_kind NOT IN ('GIFT', 'INSTALLMENT_FREE', 'RETROACTIVE')
   AND (

            b.target_category_id IN

                #{categoryId}



            OR


            b.target_merchant_id IN

                #{merchantId}


       )

   AND b.card_id NOT IN

        #{cardId}


 GROUP BY b.card_id
 ORDER BY COUNT(*) DESC, b.card_id
 LIMIT #{limit}
